CREATE TABLE public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, paddle_subscription_id text NOT NULL UNIQUE, paddle_customer_id text NOT NULL, product_id text NOT NULL, price_id text NOT NULL, status text NOT NULL DEFAULT 'active', current_period_start timestamptz, current_period_end timestamptz, cancel_at_period_end boolean NOT NULL DEFAULT false, environment text NOT NULL CHECK (environment IN ('sandbox','live')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated;
GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can read own subscriptions" ON public.subscriptions FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE INDEX idx_subscriptions_user_env ON public.subscriptions (user_id, environment, created_at DESC);
CREATE OR REPLACE FUNCTION public.has_active_subscription(user_uuid uuid, check_env text DEFAULT 'live') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.subscriptions WHERE user_id = user_uuid AND environment = check_env AND product_id = 'pro_plan' AND status IN ('active','trialing','past_due','canceled') AND (status <> 'canceled' OR current_period_end > now()) AND (current_period_end IS NULL OR current_period_end > now())) $$;
GRANT EXECUTE ON FUNCTION public.has_active_subscription(uuid,text) TO authenticated, service_role;